BloomFilter.algorithm:
class BloomFilter:
    def __init__(self, size, hash_count):
        self.size = size
        self.hash_count = hash_count
        self.bit_array = [0] * size

    def add(self, item):
        for i in range(self.hash_count):
            # Вычисляем хэш для каждой функции
            hash_val = hash(item + str(i)) % self.size
            self.bit_array[hash_val] = 1

    def check(self, item):
        for i in range(self.hash_count):
            hash_val = hash(item + str(i)) % self.size
            if self.bit_array[hash_val] == 0:
                return False  # Определенно не в множестве
        return True  # Возможно в множестве (ложноположительный возможен)
